function scale(x,y,z){const a=I();a[0]=x;a[5]=y;a[10]=z;return a;}
function rx(v){const a=I();a[5]=a[10]=Math.cos(v);a[6]=Math.sin(v);a[9]=-Math.sin(v);return a;}
function ry(v){const a=I();a[0]=a[10]=Math.cos(v);a[2]=-Math.sin(v);a[8]=Math.sin(v);return a;}
function rz(v){const a=I();a[0]=a[5]=Math.cos(v);a[1]=Math.sin(v);a[4]=-Math.sin(v);return a;}
function normalize(v){const l=Math.hypot(...v)||1;return v.map(x=>x/l);}function cross(a,b){return[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];}
