function page(angle=0,bend=0,left=false,mobile=false){const a=[],cols=mobile?25:44,rows=mobile?4:8;function point(u,v){const theta=angle+bend*Math.sin(u*Math.PI)*.34+Math.sin(angle)*Math.pow(u,4)*Math.pow(v,3)*.22;const d=2.3*u;return[(left?-1:1)*d*Math.cos(theta),.15+d*Math.sin(theta)+Math.sin(u*Math.PI)*.018,v*3.28-1.64];}function norm(u,v){const p=point(u,v),pu=point(u+.0001,v),pv=point(u,v+.0001);let n=normalize(cross(pv.map((q,i)=>q-p[i]),pu.map((q,i)=>q-p[i])));return left?n.map(q=>-q):n;}for(let j=0;j<rows;j++)for(let i=0;i<cols;i++){const u=i/cols,w=(i+1)/cols,v=j/rows,z=(j+1)/rows,uv=[[u,v],[w,v],[w,z],[u,z]],order=left?[0,1,2,0,2,3]:[0,3,2,0,2,1];order.forEach(k=>vertex(a,point(...uv[k]),norm(...uv[k]),[left?1-uv[k][0]:uv[k][0],uv[k][1]]));}return a;}
